        List<ArchivePackageRow> rows = jdbc.query(selectArchiveColumns() + " WHERE document_id = ? "
                + "AND published_version = ?", PACKAGE_MAPPER, documentId, publishedVersion);
        return rows.stream().findFirst();
    }

