import java.util.List;

/**
 * 发布撤回、术语退役与译文归档包 API 的请求与响应体。
 * 所有时间字段均为 UTC ISO-8601 毫秒精度字符串（如 2026-09-29T08:30:00.123Z），null 表示该事件尚未发生。
 */
public final class ArchiveDtos {

    private ArchiveDtos() {
    }

